window.MOTIF_CATALOG_CHUNKS[20]={"cards":[{"id":"ML-T02039","row_version":2,"title":"불협화음","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"불협화음은 서로 어울림이 불안정하거나 긴장을 일으키는 음들의 결합이다. 긴장과 불안정성이 표현 효과로 드러날 때 적용하고, 단순히 낯선 음색이나 큰 음량을 불협화음으로 부르지 않는다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"불협화음","entry_url":"cards/ML-T02039/index.html"},{"id":"ML-T02040","row_version":2,"title":"반복 리듬","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"반복 리듬은 일정한 박자나 리듬 패턴이 되풀이되어 추진력과 규칙성을 만드는 방식이다. 같은 리듬의 반복이 청각적 효과를 낼 때 적용하고, 선율이나 가사가 반복되는 것과 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"반복 리듬","entry_url":"cards/ML-T02040/index.html"},{"id":"ML-T02041","row_version":2,"title":"변박","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"변박은 곡의 진행 중 박자표나 한 마디의 박 구조가 바뀌는 것이다. 박의 단위와 묶임이 실제로 전환될 때 적용하고, 같은 박자 안에서 리듬만 달라지는 경우와 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"변박","entry_url":"cards/ML-T02041/index.html"},{"id":"ML-T02042","row_version":2,"title":"템포 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"템포 변화는 곡이 진행되는 속도가 빨라지거나 느려지는 변화다. 박의 진행 속도 자체가 달라질 때 적용하고, 박자 구조가 바뀌는 변박이나 음표가 촘촘해지는 변화와 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"템포 변화","entry_url":"cards/ML-T02042/index.html"},{"id":"ML-T02043","row_version":2,"title":"전조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"전조는 곡의 중심 조성이 다른 조성으로 옮겨가는 변화다. 음들의 조성적 중심이 실제로 이동할 때 적용하고, 일시적인 화음 변화나 선율의 높낮이 변화와 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"전조","entry_url":"cards/ML-T02043/index.html"},{"id":"ML-T02044","row_version":2,"title":"점층적 편곡","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02036","tag_path":[],"summary":"점층적 편곡은 곡이 진행되며 악기층, 음역, 밀도 또는 강세를 단계적으로 더해 음악의 규모와 강도를 키우는 구성이다. 편성의 누적이 상승감을 만들 때 적용하고, 음량만 연속해서 높이는 변화와 구별한다.","accent":"#8A7893","tab":"#528982","facet":"소리·음악","bookmark":"점층적 편곡","entry_url":"cards/ML-T02044/index.html"},{"id":"ML-T02045","row_version":2,"title":"목소리·가창","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"목소리·가창은 말하거나 노래하는 목소리의 음색, 발성, 전달 방식과 그 표현 효과를 다룬다. 목소리의 소리 자체가 장면이나 곡에서 중요한 역할을 할 때 적용하고, 가사의 문학적 의미만을 분석하는 경우와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"목소리·가창","entry_url":"cards/ML-T02045/index.html"},{"id":"ML-T02046","row_version":2,"title":"속삭임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"속삭임은 성대를 강하게 울리지 않고 낮은 호흡성 소리로 말하거나 노래하는 발성이다. 작은 음량과 가까운 청각적 거리감이 효과를 만들 때 적용하고, 단지 조용한 목소리나 낮은 음높이와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"속삭임","entry_url":"cards/ML-T02046/index.html"},{"id":"ML-T02047","row_version":2,"title":"비명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"비명은 공포, 고통, 놀람 등으로 목소리를 갑자기 높고 강하게 내지르는 발성이다. 발성의 급격한 분출이 장면의 반응이나 충격을 드러낼 때 적용하고, 노래의 고음이나 의도적인 고함과 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"비명","entry_url":"cards/ML-T02047/index.html"},{"id":"ML-T02048","row_version":2,"title":"무표정한 발화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"무표정한 발화는 감정의 높낮이를 거의 드러내지 않는 평평하고 절제된 말하기다. 내용과 목소리의 감정 표현이 의도적으로 분리될 때 적용하고, 차분하지만 억양과 감정이 분명한 발화와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"무표정한 발화","entry_url":"cards/ML-T02048/index.html"},{"id":"ML-T02049","row_version":2,"title":"울먹임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"울먹임은 울음을 참거나 흘리는 상태가 목소리에 묻어나 발화가 떨리고 끊기는 방식이다. 말소리나 노래에서 눈물과 호흡의 흔적이 들릴 때 적용하고, 실제 발화와 연결되지 않은 배경의 울음 효과와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"울먹임","entry_url":"cards/ML-T02049/index.html"},{"id":"ML-T02050","row_version":2,"title":"독창","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"독창은 한 사람이 중심이 되어 선율을 노래하는 가창 방식이다. 한 목소리가 곡의 주된 선율을 담당할 때 적용하고, 여러 목소리가 함께 선율이나 화음을 이루는 합창과 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"독창","entry_url":"cards/ML-T02050/index.html"},{"id":"ML-T02051","row_version":2,"title":"합창","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"합창은 여러 사람이 함께 노래해 선율을 unison으로 부르거나 여러 성부와 화음을 이루는 방식이다. 복수의 가창자가 집단적 음향을 형성할 때 적용하고, 한 사람의 노래에 악기 반주나 녹음된 겹침만 더해진 경우와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"합창","entry_url":"cards/ML-T02051/index.html"},{"id":"ML-T02052","row_version":2,"title":"주고받는 노래","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"두 사람이나 집단이 노래 구절을 번갈아 부르며, 한쪽의 소리가 다른 쪽의 응답을 이끈다. 화답이나 역할 교대가 음악의 구조로 드러날 때 적용하고, 단순히 여러 목소리가 함께 부르는 합창과 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"주고받는 노래","entry_url":"cards/ML-T02052/index.html"},{"id":"ML-T02053","row_version":2,"title":"랩","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"말하듯 리듬에 맞춰 음절과 운율을 얹어 전달하는 가창 방식이다. 선율을 길게 부르는 노래와 달리 언어의 박자와 발음이 중심일 때 적용하고, 말에 배경음악만 흐르는 경우와 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"랩","entry_url":"cards/ML-T02053/index.html"},{"id":"ML-T02054","row_version":2,"title":"허밍","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02045","tag_path":[],"summary":"입을 다문 채 성대의 울림으로 음높이와 선율을 내는 발성이다. 가사 없이 목소리로 선율을 이어갈 때 적용하고, 숨소리나 입술을 떠는 소리처럼 음정이 뚜렷하지 않은 발성과 구별한다.","accent":"#8A7893","tab":"#7D8FA3","facet":"소리·음악","bookmark":"허밍","entry_url":"cards/ML-T02054/index.html"},{"id":"ML-T02055","row_version":2,"title":"악기·음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"악기의 종류와 연주·처리 방식이 만들어내는 음색을 통해 소리의 성격을 구성하는 요소다. 특정 악기군의 소리가 청각적 인상이나 장면의 의미를 좌우할 때 적용하고, 음량·속도·화성 같은 다른 음악 요소와 구별한다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"악기·음색","entry_url":"cards/ML-T02055/index.html"},{"id":"ML-T02056","row_version":2,"title":"현악 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"현을 뜯거나 켜고 두드려 내는 악기에서 비롯된, 줄의 울림과 공명 특성이 드러나는 소리다. 현의 떨림이 음색의 주요 단서일 때 적용하고, 현악기처럼 들리도록 합성했더라도 실제 악기군을 특정하는 분류와는 구별한다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"현악 음색","entry_url":"cards/ML-T02056/index.html"},{"id":"ML-T02057","row_version":2,"title":"관악 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"관 속의 공기를 불어넣거나 진동시켜 내는 악기의 음색으로, 호흡감과 관의 울림이 특징을 이룬다. 관악기의 숨결이나 발음 특성이 들릴 때 적용하고, 단지 길게 이어지는 음이나 숨소리가 섞인 보컬과 구별한다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"관악 음색","entry_url":"cards/ML-T02057/index.html"},{"id":"ML-T02058","row_version":2,"title":"타악 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"물체를 치거나 흔들고 긁어 리듬과 음색을 만드는 악기의 소리다. 타격감이나 흔들림의 질감이 음악적 인상을 형성할 때 적용하고, 박자 표기나 소리의 크기처럼 악기 음색 자체가 아닌 특성과 구별한다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"타악 음색","entry_url":"cards/ML-T02058/index.html"},{"id":"ML-T02059","row_version":2,"title":"건반 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"건반을 눌러 음을 내는 악기에서 비롯된 소리로, 음의 시작과 배열이 건반 연주 특성을 드러낸다. 피아노나 오르간 계열의 음색이 중심일 때 적용하고, 건반으로 연주했다는 사실만으로 다른 악기 음색까지 이 범주에 넣지 않는다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"건반 음색","entry_url":"cards/ML-T02059/index.html"},{"id":"ML-T02060","row_version":2,"title":"전자 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"전자 회로나 디지털 신호의 생성·변형으로 만들어지는 소리다. 합성음이나 전자적 처리가 고유한 음색을 이루는 경우 적용하고, 녹음된 악기 소리에 효과를 더했다는 이유만으로 전자 음색으로 단정하지 않는다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"전자 음색","entry_url":"cards/ML-T02060/index.html"},{"id":"ML-T02061","row_version":2,"title":"민속악기 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"특정 지역이나 전통의 음악 문화와 연결된 악기에서 나는 소리다. 악기의 전승 맥락이나 식별 가능한 연주법이 음색을 구별할 때 적용하고, 막연히 이국적이거나 전통적으로 들린다는 인상만으로 분류하지 않는다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"민속악기 음색","entry_url":"cards/ML-T02061/index.html"},{"id":"ML-T02062","row_version":3,"title":"노이즈 음색","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02055","tag_path":[],"summary":"불규칙한 잡음, 거친 질감, 왜곡처럼 안정된 음높이나 맑은 음색에서 벗어난 소리다. 잡음성이 음악의 표현 요소로 두드러질 때 적용하고, 녹음 결함이나 배경의 우연한 소음과 구별한다.","accent":"#8A7893","tab":"#A07A87","facet":"소리·음악","bookmark":"노이즈 음색","entry_url":"cards/ML-T02062/index.html"},{"id":"ML-T02063","row_version":3,"title":"소리와 장면의 연결","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"group","parent_id":"ML-F24","tag_path":[],"summary":"소리의 발생·변화·배치가 화면의 장면이나 서사 진행과 의미 있게 맞물리는 구성이다. 소리와 장면 사이의 연결 방식이 해석이나 전환에 기여할 때 적용하고, 장면에 단순히 배경으로 깔린 음악과 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"소리와 장면의 연결","entry_url":"cards/ML-T02063/index.html"},{"id":"ML-T02064","row_version":3,"title":"사운드 브리지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"앞 장면의 소리가 화면 전환을 넘어 다음 장면까지 이어져 두 장면을 청각적으로 잇는 방식이다. 전환 전후에 같은 소리가 연속성을 만들 때 적용하고, 새 장면에서 별도로 시작하는 음악이나 효과음과 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"사운드 브리지","entry_url":"cards/ML-T02064/index.html"},{"id":"ML-T02065","row_version":3,"title":"소리 선행","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"소리가 먼저 들리고 그 뒤에 소리의 원인이나 관련 장면이 화면에 제시되는 구성이다. 청각 정보가 시각적 공개보다 앞서 기대나 긴장을 형성할 때 적용하고, 화면 밖 소리가 계속 들리지만 원인이 드러나지 않는 경우와 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"소리 선행","entry_url":"cards/ML-T02065/index.html"},{"id":"ML-T02066","row_version":2,"title":"소리 후행","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"화면의 사건이나 장면 변화가 먼저 제시된 뒤, 그에 대응하는 소리가 늦게 들리는 구성이다. 소리의 지연이 충격이나 인식의 변화를 표현할 때 적용하고, 단순한 재생 지연이나 음향 싱크 오류와 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"소리 후행","entry_url":"cards/ML-T02066/index.html"},{"id":"ML-T02067","row_version":2,"title":"동작과 음악의 동기화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"인물의 동작이나 편집된 움직임이 음악의 박자·강세·악구와 맞물려 진행되는 연출이다. 움직임의 타이밍이 음악 구조에 맞춰 반복되거나 강조될 때 적용하고, 우연히 박자와 비슷해 보이는 움직임과 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"동작과 음악의 동기화","entry_url":"cards/ML-T02067/index.html"},{"id":"ML-T02068","row_version":2,"title":"소리의 반복 변주","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"같은 소리나 음악적 구절이 되풀이되면서 음색·속도·음량·배치 등이 달라지는 방식이다. 반복될수록 변화가 의미나 긴장을 더할 때 적용하고, 거의 같은 형태로 재생되는 단순 반복과 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"소리의 반복 변주","entry_url":"cards/ML-T02068/index.html"},{"id":"ML-T02069","row_version":2,"title":"소리의 급격한 단절","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":"tag","parent_id":"ML-T02063","tag_path":[],"summary":"이어지던 음악이나 효과음이 예고 없이 끊겨 청각적 공백이나 대비를 만드는 연출이다. 단절이 장면의 충격·불안·전환에 의미 있게 작용할 때 적용하고, 자연스러운 곡의 끝이나 대사에 따른 통상적인 음악 퇴장과 구별한다.","accent":"#8A7893","tab":"#79866C","facet":"소리·음악","bookmark":"소리의 급격한 단절","entry_url":"cards/ML-T02069/index.html"},{"id":"ML-T02070","row_version":5,"title":"조작·행위","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"플레이어의 입력을 게임 규칙이 해석해 캐릭터나 시스템의 행동으로 바꾸는 방식이다. 작품을 적용할 때는 능력 자체나 서사 속 행위가 아니라, 플레이어가 어떤 입력으로 행동을 일으키는지 본다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"조작·행위","entry_url":"cards/ML-T02070/index.html"},{"id":"ML-T02071","row_version":3,"title":"이동 조작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"방향 입력을 통해 캐릭터나 탈것의 이동 방향과 속도를 제어하는 방식이다. 이동이 자동 진행되거나 선택지로만 위치가 바뀌는 경우와 구별해, 이동을 직접 입력하는 규칙을 기준으로 삼는다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"이동 조작","entry_url":"cards/ML-T02071/index.html"},{"id":"ML-T02072","row_version":3,"title":"조준","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"시야나 조준점을 움직여 공격 또는 상호작용의 대상을 겨누는 입력 방식이다. 명중률이나 사거리 같은 능력치 효과만으로는 해당하지 않으며, 겨누는 동작을 플레이어가 조절하는지 살핀다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"조준","entry_url":"cards/ML-T02072/index.html"},{"id":"ML-T02073","row_version":3,"title":"선택지 선택","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"제시된 여러 행동이나 응답 중 하나를 골라 이후 진행을 정하는 입력이다. 선택처럼 보이는 서사적 결정보다, 게임이 실제로 선택 항목을 제시하고 그 선택을 진행 규칙에 반영하는지 확인한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"선택지 선택","entry_url":"cards/ML-T02073/index.html"},{"id":"ML-T02074","row_version":3,"title":"대화 입력","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"대화 중 문장이나 키워드를 입력해 상대의 응답 또는 대화 흐름을 유도하는 방식이다. 미리 작성된 대사 선택지를 고르는 것과 구별해, 플레이어가 텍스트나 어휘를 직접 입력해야 하는지 본다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"대화 입력","entry_url":"cards/ML-T02074/index.html"},{"id":"ML-T02075","row_version":3,"title":"물체 조작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"물체를 집거나 밀고 당기고 회전시키는 등 직접 다루어 상태나 위치를 바꾸는 입력 방식이다. 물체와 관련된 퍼즐이나 능력의 존재만으로 분류하지 말고, 조작 행위가 플레이어 입력으로 구현되는지 살핀다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"물체 조작","entry_url":"cards/ML-T02075/index.html"},{"id":"ML-T02076","row_version":3,"title":"배치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"유닛, 건물, 아이템 같은 대상을 지정한 위치에 놓아 배치 상태를 만드는 입력이다. 자동 생성되는 배치나 단순한 이동과 구별해, 위치를 정하는 선택이 게임 규칙에 영향을 주는지 기준으로 삼는다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"배치","entry_url":"cards/ML-T02076/index.html"},{"id":"ML-T02077","row_version":2,"title":"타이밍 입력","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"정해진 순간이나 시간 구간에 맞춰 버튼·명령을 입력해 성공 여부나 효과를 판정받는 방식이다. 입력 속도가 전반적으로 중요하다는 이유만으로 포함하지 말고, 특정 타이밍이 판정 조건으로 명시되는지 본다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"타이밍 입력","entry_url":"cards/ML-T02077/index.html"},{"id":"ML-T02078","row_version":2,"title":"제스처 입력","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02070","tag_path":[],"summary":"화면을 누르거나 그리는 등 손의 움직임과 모양을 입력값으로 삼는 방식이다. 동작이 연출에만 쓰이는 경우는 제외하고, 제스처의 방향·형태·경로가 게임 행동이나 판정을 결정하는지 확인한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"제스처 입력","entry_url":"cards/ML-T02078/index.html"},{"id":"ML-T02079","row_version":3,"title":"탐색·공간","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"공간을 이동하고 관찰하거나 그 구조와 상호작용하는 플레이 규칙을 가리킨다. 배경에 장소가 등장하는 것만으로는 부족하며, 공간의 구성이나 이동이 선택·진행·문제 해결에 실제 영향을 주는지 살핀다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"탐색·공간","entry_url":"cards/ML-T02079/index.html"},{"id":"ML-T02080","row_version":2,"title":"오픈월드 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"넓은 공간을 비교적 자유롭게 이동하며 여러 활동과 목표를 원하는 순서로 수행하도록 구성한 구조다. 맵이 크다는 사실만으로 적용하지 말고, 이동 경로와 활동 순서에 실질적인 선택권이 있는지 본다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"오픈월드 구조","entry_url":"cards/ML-T02080/index.html"},{"id":"ML-T02081","row_version":4,"title":"샌드박스 구조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"정해진 목표를 따라가는 대신 플레이어가 도구와 규칙을 활용해 활동이나 결과를 만들어 가는 구조다. 넓은 맵이나 자유 이동만으로 판단하지 말고, 목표 수행 외의 실험·창작·자율 활동이 허용되는지 확인한다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"샌드박스 구조","entry_url":"cards/ML-T02081/index.html"},{"id":"ML-T02082","row_version":2,"title":"구역 해금","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"조건 충족이나 진행에 따라 이전에 접근할 수 없던 공간을 이용 가능하게 만드는 규칙이다. 단순히 문이나 통로를 여는 장면보다, 그 결과 탐색 가능한 구역의 범위가 확장되는지 기준으로 삼는다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"구역 해금","entry_url":"cards/ML-T02082/index.html"},{"id":"ML-T02083","row_version":2,"title":"안개 지도","original":"Fog of War","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"전략 게임에서 아직 탐색하지 않았거나 현재 관측할 수 없는 구역과 적 정보를 화면에서 숨기는 규칙이다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"안개 지도","entry_url":"cards/ML-T02083/index.html"},{"id":"ML-T02084","row_version":2,"title":"숨겨진 길","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"눈에 잘 띄지 않거나 우회해야 발견되는 통로로 이동 경로를 확장하는 공간 요소다. 막다른 길이나 장식용 틈과 구별해, 실제로 통과할 수 있고 탐색 또는 진행에 쓰이는지를 확인한다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"숨겨진 길","entry_url":"cards/ML-T02084/index.html"},{"id":"ML-T02085","row_version":2,"title":"되돌아가기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"새 능력이나 단서, 열린 경로를 얻은 뒤 이전에 방문한 공간으로 돌아가 다시 탐색하는 진행 방식이다. 단순한 반복 방문이 아니라, 돌아간 결과 새 경로·보상·상호작용이 가능해지는지 살핀다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"되돌아가기","entry_url":"cards/ML-T02085/index.html"},{"id":"ML-T02086","row_version":3,"title":"절차적 생성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"공간이나 아이템, 사건 등의 일부를 알고리즘으로 생성해 플레이마다 구성을 달리하는 방식이다. 미리 만든 콘텐츠의 무작위 배치와 구별할 때는, 규칙에 따라 콘텐츠 자체의 구조나 조합이 생성되는지 본다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"절차적 생성","entry_url":"cards/ML-T02086/index.html"},{"id":"ML-T02087","row_version":2,"title":"환경 퍼즐","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02079","tag_path":[],"summary":"환경의 구조나 물체, 장치를 관찰하고 조작해 해결하는 문제다. 단순히 배경에서 벌어지는 수수께끼가 아니라, 환경의 성질을 이해하고 행동을 조합해야 진행되는지 기준으로 적용한다.","accent":"#667E94","tab":"#778F70","facet":"게임·상호작용","bookmark":"환경 퍼즐","entry_url":"cards/ML-T02087/index.html"},{"id":"ML-T02088","row_version":3,"title":"진행·성장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"플레이가 진행되며 캐릭터나 기반, 선택 가능성이 변하고 확장되는 체계다. 이야기상 성장 묘사와 구별해, 규칙·능력·자원 또는 활동 범위에 지속적인 변화가 생기는지 본다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"진행·성장","entry_url":"cards/ML-T02088/index.html"},{"id":"ML-T02089","row_version":3,"title":"레벨업","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"경험치나 조건을 충족하면 레벨이 오르고 능력치 또는 선택 가능한 기능이 갱신되는 성장 규칙이다. 숫자나 단계가 표시되는 것만으로는 부족하며, 레벨 상승이 플레이 조건이나 능력에 변화를 주는지 확인한다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"레벨업","entry_url":"cards/ML-T02089/index.html"},{"id":"ML-T02090","row_version":3,"title":"스킬트리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"능력이나 특성을 노드·분기 형태로 제시하고, 선택한 경로에 따라 습득 내용을 달리하는 성장 체계다. 선형으로 능력을 하나씩 받는 진행과 구별해, 선택의 갈래가 빌드나 기능 조합에 영향을 주는지 본다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"스킬트리","entry_url":"cards/ML-T02090/index.html"},{"id":"ML-T02091","row_version":3,"title":"장비 성장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"장비를 강화하거나 등급·성능을 높여 전투 또는 활동 효율을 바꾸는 성장 방식이다. 더 강한 장비를 단순히 획득하는 것과 구별해, 보유 장비의 상태를 개선하는 규칙이 있는지 살핀다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"장비 성장","entry_url":"cards/ML-T02091/index.html"},{"id":"ML-T02092","row_version":4,"title":"캐릭터 육성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"특정 캐릭터의 능력·특성·상태를 선택과 자원 투입으로 장기적으로 바꾸는 과정이다. 캐릭터가 이야기에서 성숙하는 것만으로는 해당하지 않으며, 플레이 선택이 캐릭터의 기능이나 성능을 변화시키는지 본다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"캐릭터 육성","entry_url":"cards/ML-T02092/index.html"},{"id":"ML-T02093","row_version":3,"title":"관계도 성장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"인물 간 관계 수치나 단계가 상호작용과 선택에 따라 변하고, 그 변화가 콘텐츠나 기능에 반영되는 체계다. 관계 묘사만 있는 경우와 구별해, 관계의 변화가 규칙상 측정되거나 해금·효과를 낳는지 확인한다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"관계도 성장","entry_url":"cards/ML-T02093/index.html"},{"id":"ML-T02094","row_version":2,"title":"거점 확장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"거점에 시설이나 기능을 추가해 이용 범위와 운영 능력을 점차 늘리는 성장 방식이다. 거점의 외형 변화에 그치지 않고, 확장이 활동·생산·회복 등 플레이 기능에 영향을 주는지 기준으로 삼는다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"거점 확장","entry_url":"cards/ML-T02094/index.html"},{"id":"ML-T02095","row_version":3,"title":"메타 성장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"한 회차나 캐릭터의 진행이 끝난 뒤에도 다음 도전에 이어지는 해금·강화 요소를 통해 장기적으로 성장하는 구조다. 회차 안에서만 유지되는 레벨이나 장비와 구별해, 진행 단위를 넘어 효과가 지속되는지 본다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"메타 성장","entry_url":"cards/ML-T02095/index.html"},{"id":"ML-T02096","row_version":4,"title":"지식 기반 성장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02088","tag_path":[],"summary":"플레이어가 단서와 규칙을 배워 얻은 지식이 이후 선택이나 문제 해결 능력을 바꾸는 성장 방식이다. 캐릭터 수치가 오르는 성장과 구별해, 저장된 정보나 학습한 원리가 다음 상황에서 실질적인 이점으로 작동하는지 살핀다.","accent":"#667E94","tab":"#8B739C","facet":"게임·상호작용","bookmark":"지식 기반 성장","entry_url":"cards/ML-T02096/index.html"},{"id":"ML-T02097","row_version":3,"title":"경제·자원","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"게임 안에서 얻고 보유하며 교환하거나 사용하는 재화와 자원의 흐름을 다루는 규칙이다. 배경 설정에 자원이 언급되는 것만으로 분류하지 말고, 획득·보유·교환·지출이 플레이 선택에 영향을 주는지 본다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"경제·자원","entry_url":"cards/ML-T02097/index.html"},{"id":"ML-T02098","row_version":2,"title":"체력 자원","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"피해를 견디거나 생존 상태를 유지하기 위해 관리하는 체력 수치 또는 이에 준하는 자원이다. 실패 횟수나 생명 수와 혼동하지 말고, 전투·위험 상황에서 소모와 회복이 생존 판정에 연결되는지 확인한다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"체력 자원","entry_url":"cards/ML-T02098/index.html"},{"id":"ML-T02099","row_version":2,"title":"행동력 자원","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"행동 횟수나 능력 사용을 제한하며 특정 행동에 소모되는 포인트나 게이지다. 체력이나 시간과 구별해, 행동을 수행할 수 있는 여력을 별도로 계산하고 회복·충전을 규칙화하는지 본다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"행동력 자원","entry_url":"cards/ML-T02099/index.html"},{"id":"ML-T02100","row_version":3,"title":"시간 자원","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"행동이나 대기, 일정의 진행에 따라 줄거나 소비되며 선택 가능한 활동을 제한하는 시간 단위다. 배경상 시간이 흐르는 연출이 아니라, 시간 경과가 마감·위험·행동 기회 같은 규칙적 결과를 낳는지 살핀다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"시간 자원","entry_url":"cards/ML-T02100/index.html"},{"id":"ML-T02101","row_version":2,"title":"인벤토리 제한","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"소지품의 개수나 무게, 칸 수를 제한해 무엇을 보유할지 선택하게 하는 규칙이다. 아이템 보유 목록이 있다는 사실만으로 적용하지 말고, 한도 때문에 획득·정리·휴대 결정이 필요해지는지 본다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"인벤토리 제한","entry_url":"cards/ML-T02101/index.html"},{"id":"ML-T02102","row_version":2,"title":"제작 재료","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"제작법에 따라 아이템이나 장비를 만들 때 필요한 투입 자원이다. 단순히 수집 가능한 아이템과 구별해, 정해진 재료가 제작 과정의 비용 또는 조건으로 소비되는지 확인한다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"제작 재료","entry_url":"cards/ML-T02102/index.html"},{"id":"ML-T02103","row_version":3,"title":"거래 시스템","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"플레이어 또는 게임 내 인물·세력 사이에서 재화나 물품을 주고받는 규칙이다. 상점에서 일방적으로 구매하는 기능과 구별할 때는, 교환 상대와 거래 조건이 시스템으로 표현되는지 살핀다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"거래 시스템","entry_url":"cards/ML-T02103/index.html"},{"id":"ML-T02104","row_version":2,"title":"자원 생산","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"행동이나 시설, 시간 경과에 따라 자원이 새로 만들어지거나 정기적으로 유입되는 규칙이다. 단순한 보상 획득과 구별해, 반복 가능한 생산 원천이나 생산 조건이 마련되어 있는지 본다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"자원 생산","entry_url":"cards/ML-T02104/index.html"},{"id":"ML-T02105","row_version":3,"title":"자원 소비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02097","tag_path":[],"summary":"행동·유지·제작 등에 자원을 지불하거나 소모하도록 정한 규칙이다. 자원이 줄어드는 연출만으로 판단하지 말고, 소모가 선택의 비용이나 반복 행동의 제약으로 기능하는지 확인한다.","accent":"#667E94","tab":"#A58A4E","facet":"게임·상호작용","bookmark":"자원 소비","entry_url":"cards/ML-T02105/index.html"},{"id":"ML-T02106","row_version":4,"title":"전투·경쟁","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"적이나 다른 플레이어와 겨루며 승패·우위·목표 달성을 판정하는 규칙과 행동을 가리킨다. 갈등이 이야기의 소재로만 나타나는 경우와 구별해, 플레이 수행과 결과 판정이 경쟁 구조를 이루는지 본다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/ML-T02106/index.html"},{"id":"ML-T02107","row_version":2,"title":"턴제 전투","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"행동이 차례 단위로 나뉘고, 각 차례에 가능한 명령이나 순서가 전투 결과에 영향을 주는 방식이다. 실시간 상황에서 잠시 입력을 멈추는 기능과 구별해, 규칙상 행동 기회가 턴으로 배분되는지 기준으로 삼는다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"턴제 전투","entry_url":"cards/ML-T02107/index.html"},{"id":"ML-T02108","row_version":3,"title":"실시간 전투","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"전투 행동과 상대의 반응이 연속적으로 진행되며, 플레이어가 진행 중 입력으로 공격·방어·이동을 제어하는 방식이다. 턴 구분이 있는 전투와 구별해, 행동 기회가 순번보다 시간 흐름에 따라 처리되는지 본다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"실시간 전투","entry_url":"cards/ML-T02108/index.html"},{"id":"ML-T02109","row_version":2,"title":"위치 선정","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"전투에서 캐릭터나 유닛을 특정 위치에 두어 사거리, 엄폐, 공격 가능성 같은 전술 조건을 바꾸는 선택이다. 위치가 시각적으로 보이는 것만으로는 부족하며, 배치 장소가 전투 효율이나 가능한 행동에 영향을 주는지 살핀다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"위치 선정","entry_url":"cards/ML-T02109/index.html"},{"id":"ML-T02110","row_version":3,"title":"상성 시스템","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"속성·유형·상태 사이의 우열 관계를 정해 특정 조합에서 효과나 피해를 달리하는 규칙이다. 적의 외형이나 서사적 약점만으로 적용하지 말고, 반복 가능한 상호작용 규칙으로 강약이 판정되는지 확인한다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"상성 시스템","entry_url":"cards/ML-T02110/index.html"},{"id":"ML-T02111","row_version":2,"title":"콤보","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"공격이나 행동을 정해진 순서 또는 조건으로 이어 성공 보상이나 추가 효과를 얻는 연결 규칙이다. 단순히 여러 번 공격하는 장면과 구별해, 연속 입력·순서·간격이 판정되고 그 결과가 달라지는지 본다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"콤보","entry_url":"cards/ML-T02111/index.html"},{"id":"ML-T02112","row_version":2,"title":"패링","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"상대 공격에 맞춰 방어 입력을 성공시키면 피해를 막거나 상대를 빈틈에 빠뜨리는 기술 규칙이다. 일반 방어처럼 언제든 막는 동작과 구별해, 공격 순간에 맞춘 입력이 성공 조건인지 확인한다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"패링","entry_url":"cards/ML-T02112/index.html"},{"id":"ML-T02113","row_version":3,"title":"보스 패턴","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"보스가 특정 순서나 조건에 따라 반복·변형해 사용하는 공격과 행동의 규칙이다. 강한 적이라는 설정만으로는 해당하지 않으며, 플레이어가 관찰하고 대응할 수 있는 식별 가능한 행동 패턴이 있는지 본다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"보스 패턴","entry_url":"cards/ML-T02113/index.html"},{"id":"ML-T02114","row_version":3,"title":"비대칭 대전","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02106","tag_path":[],"summary":"서로 다른 역할·능력·목표를 가진 편들이 대전하고, 각 편의 비대칭성이 승부 방식에 반영되는 구조다. 팀 수가 다르거나 캐릭터 성능이 다른 것만으로 판단하지 말고, 역할과 승리 조건의 차이가 전략을 다르게 만드는지 살핀다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"비대칭 대전","entry_url":"cards/ML-T02114/index.html"},{"id":"ML-T02115","row_version":3,"title":"제작·수집","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"물품이나 생물, 장소 등을 모으고, 조합하거나 가공해 새로운 결과물을 만드는 플레이 활동이다. 획득만 있는 경우와 제작만 있는 경우를 구분해, 수집과 제작의 어떤 과정이 실제 규칙으로 구현되는지 적용한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"제작·수집","entry_url":"cards/ML-T02115/index.html"},{"id":"ML-T02116","row_version":2,"title":"수집 도감","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"발견하거나 획득한 항목을 기록해 목록의 완성도와 수집 현황을 관리하는 체계다. 아이템을 많이 모으는 플레이와 구별해, 항목별 기록·등록이나 완성 목표가 시스템으로 제공되는지 확인한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"수집 도감","entry_url":"cards/ML-T02116/index.html"},{"id":"ML-T02117","row_version":2,"title":"조합 제작","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"둘 이상의 재료나 아이템을 정해진 조리법·공식에 따라 결합해 다른 결과물을 만드는 제작 방식이다. 단순 강화나 한 재료의 가공과 구별해, 복수 요소의 조합이 결과를 결정하는지 본다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"조합 제작","entry_url":"cards/ML-T02117/index.html"},{"id":"ML-T02118","row_version":2,"title":"머지","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"같거나 호환되는 항목을 합쳐 더 높은 단계나 새로운 항목으로 바꾸는 규칙이다. 일반 제작과 구별할 때는, 조합법 입력보다 동일·유사 항목의 병합 자체가 핵심 변환 조건인지 살핀다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"머지","entry_url":"cards/ML-T02118/index.html"},{"id":"ML-T02119","row_version":2,"title":"건설","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"재료나 자원을 사용해 구조물·시설을 세우고 공간에 지속적으로 남기는 활동이다. 장식 배치와 구별해, 건축 결과가 공간 이용이나 기능에 영향을 주는지 또는 건설 자체가 핵심 플레이인지 확인한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"건설","entry_url":"cards/ML-T02119/index.html"},{"id":"ML-T02120","row_version":2,"title":"수리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"손상되거나 내구도가 줄어든 장비·구조물을 자원이나 행동을 들여 다시 사용할 수 있는 상태로 회복하는 규칙이다. 새 장비로 교체하거나 강화하는 것과 구별해, 기존 대상의 손상·고장을 복구하는 과정인지 본다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"수리","entry_url":"cards/ML-T02120/index.html"},{"id":"ML-T02121","row_version":4,"title":"요리 시스템","original":"Cooking Mechanics","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"플레이어가 재료를 조합해 음식을 만들고 그 결과를 회복이나 진행에 사용하는 게임 규칙.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"요리 시스템","entry_url":"cards/ML-T02121/index.html"},{"id":"ML-T02122","row_version":2,"title":"재배","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"재배는 씨앗이나 개체를 심고 돌보아 시간이 지나면 작물이나 자원을 얻는 규칙이다. 성장 조건과 수확 주기가 핵심이면 해당하며, 단순히 아이템을 제작하는 과정과는 구별한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"재배","entry_url":"cards/ML-T02122/index.html"},{"id":"ML-T02123","row_version":2,"title":"채굴","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"채굴은 지형이나 광맥을 캐서 광물·재료를 획득하는 행동과 규칙이다. 자원 매장지에 도구나 행동을 사용해 채취하는 경우를 가리키며, 적을 처치해 재료를 얻는 일과는 구별한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"채굴","entry_url":"cards/ML-T02123/index.html"},{"id":"ML-T02124","row_version":2,"title":"포획","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02115","tag_path":[],"summary":"포획은 대상의 상태를 제압하거나 특정 조건을 충족해 소유·관리 가능한 개체로 만드는 규칙이다. 포획 성공이 게임 진행의 결과로 처리되는 경우에 적용하며, 단순 처치나 일시적 구속과 구별한다.","accent":"#667E94","tab":"#7D8FA3","facet":"게임·상호작용","bookmark":"포획","entry_url":"cards/ML-T02124/index.html"},{"id":"ML-T02125","row_version":5,"title":"선택·서사","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"선택·서사는 플레이어의 결정이 이야기의 정보, 인물 관계, 사건 전개나 결말에 영향을 주는 구조다. 대화 선택지의 존재만으로 분류하지 말고, 선택이 서사적으로 유의미한 결과를 낳는지 살핀다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"선택·서사","entry_url":"cards/ML-T02125/index.html"},{"id":"ML-T02126","row_version":3,"title":"분기 선택","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"분기 선택은 결정에 따라 이후 장면이나 사건 경로가 서로 다른 갈래로 진행되는 구조다. 갈림길이 실제 전개를 나누는 경우에 해당하며, 표현만 달라지고 같은 경로로 합쳐지는 선택과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"분기 선택","entry_url":"cards/ML-T02126/index.html"},{"id":"ML-T02127","row_version":3,"title":"도덕적 선택","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"도덕적 선택은 선악, 의무, 책임처럼 가치 판단이 필요한 대안 중 하나를 고르게 하는 결정이다. 선택의 기준이 윤리적 갈등에 있을 때 적용하며, 단순히 전투 효율이나 보상을 비교하는 선택과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"도덕적 선택","entry_url":"cards/ML-T02127/index.html"},{"id":"ML-T02128","row_version":3,"title":"관계 선택","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"관계 선택은 특정 인물에 대한 태도나 행동을 정해 친밀도, 신뢰, 갈등 같은 관계 상태에 영향을 주는 결정이다. 결과가 인물 간 관계에 반영되어야 하며, 관계 변화 없이 대사만 바뀌는 선택과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"관계 선택","entry_url":"cards/ML-T02128/index.html"},{"id":"ML-T02129","row_version":3,"title":"선택의 지연 결과","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"선택의 지연 결과는 결정 직후에는 결과가 드러나지 않고 나중 사건이나 장면에서 영향이 나타나는 구조다. 앞선 선택과 뒤의 변화 사이에 인과가 연결될 때 적용하며, 단순한 결과 안내의 지연과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"선택의 지연 결과","entry_url":"cards/ML-T02129/index.html"},{"id":"ML-T02130","row_version":3,"title":"선택의 영속성","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"선택의 영속성은 결정이 저장되거나 이후 진행에 유지되어 되돌리기 어려운 영향을 남기는 성질이다. 재시작이나 특정 초기화 없이 결과가 이어지는지를 기준으로 삼고, 언제든 취소 가능한 임시 선택과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"선택의 영속성","entry_url":"cards/ML-T02130/index.html"},{"id":"ML-T02131","row_version":4,"title":"위장된 선택","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"위장된 선택은 선택지가 의미 있는 차이를 약속하는 듯 보이지만 실제 결과나 경로가 같도록 구성된 결정이다. 플레이어가 인식하는 선택과 시스템의 실질적 분기 사이의 불일치가 핵심이며, 단순한 선택 결과의 예측 불가능성과 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"위장된 선택","entry_url":"cards/ML-T02131/index.html"},{"id":"ML-T02132","row_version":5,"title":"다중 결말","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02125","tag_path":[],"summary":"다중 결말은 플레이 과정의 조건이나 선택에 따라 서로 다른 최종 서사 상태에 도달하는 구조다. 결말 자체가 복수로 존재해야 하며, 같은 결말의 연출 차이나 후일담 변형만 있는 경우와 구별한다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"다중 결말","entry_url":"cards/ML-T02132/index.html"},{"id":"ML-T02133","row_version":3,"title":"보상·실패","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"group","parent_id":"ML-F25","tag_path":[],"summary":"보상·실패는 행동이나 도전의 결과를 보상 획득 또는 목표 미달로 처리하는 게임 규칙의 묶음이다. 성취와 실패가 어떤 조건과 결과로 판정되는지 볼 때 쓰며, 단순한 서사적 성공·좌절 묘사와 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"보상·실패","entry_url":"cards/ML-T02133/index.html"},{"id":"ML-T02134","row_version":2,"title":"확정 보상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"확정 보상은 정해진 조건을 충족하면 결과가 무작위 추첨 없이 보장되는 보상이다. 동일 조건에서 획득 여부가 확정되는 구조에 적용하며, 보상 종류나 수량이 확률에 따라 달라지는 방식과 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"확정 보상","entry_url":"cards/ML-T02134/index.html"},{"id":"ML-T02135","row_version":3,"title":"무작위 보상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"무작위 보상은 획득 결과나 보상의 종류가 확률에 따라 결정되는 구조다. 결과의 불확실성이 규칙에 포함될 때 해당하며, 보상 획득 자체는 확정이고 그 내용만 고정된 경우와 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"무작위 보상","entry_url":"cards/ML-T02135/index.html"},{"id":"ML-T02136","row_version":2,"title":"누적 보상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"누적 보상은 여러 행동이나 진행 단계에서 쌓인 수치·자원이 일정 기준에 도달하면 주어지는 보상이다. 이전의 기여가 총량으로 더해져 보상 조건을 이루는 경우에 적용하며, 한 번의 행동으로 즉시 얻는 보상과 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"누적 보상","entry_url":"cards/ML-T02136/index.html"},{"id":"ML-T02137","row_version":3,"title":"연속 보상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"연속 보상은 정해진 행동이나 승리를 끊기지 않고 이어갈 때 추가 이득을 주는 구조다. 연속 기록의 유지가 보상 조건인 경우를 가리키며, 여러 차례의 성과를 합산하는 누적 보상과 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"연속 보상","entry_url":"cards/ML-T02137/index.html"},{"id":"ML-T02138","row_version":3,"title":"영구 사망","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":"tag","parent_id":"ML-T02133","tag_path":[],"summary":"영구 사망은 캐릭터의 사망 뒤 해당 진행 상태나 캐릭터를 되살리거나 이어갈 수 없게 하는 규칙이다. 사망이 진행의 영구적 상실로 연결되어야 하며, 체크포인트에서 재개하거나 부활 자원을 쓰는 방식과 구별한다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"영구 사망","entry_url":"cards/ML-T02138/index.html"}]}.cards;